def _fingerprint(account_id: int, day: str, cents: int, occurrence: int) -> str:
    """Frozen copy of the v2 rule in `ledger/dedup.py` as of this migration."""
    payload = f"v2|{account_id}|{day}|{cents}|{occurrence}"
