def _recompute_fingerprints() -> None:
    """Dedup v2 drops the description from fingerprints; recompute them for existing rows.

    Occurrences are counted per import batch and account, in insertion order, as an import
    would. When two batches hold the same (account, date, amount) under the old rule, the
    later row takes the next free occurrence, so no row is lost or merged.
    """
    bind = op.get_bind()
    rows = bind.execute(sa.text(
        "SELECT id, account_id, date, amount_cents, import_batch_id FROM transactions "
        "ORDER BY import_batch_id, id"
    )).all()
    seen: Counter[tuple[object, ...]] = Counter()
    used: set[str] = set()
    for row_id, account_id, day, cents, batch_id in rows:
        key = (batch_id, account_id, str(day), cents)
        occurrence = seen[key]
        seen[key] += 1
        value = _fingerprint(account_id, str(day), cents, occurrence)
        while value in used:
            occurrence += 1
            value = _fingerprint(account_id, str(day), cents, occurrence)
        used.add(value)
        bind.execute(sa.text("UPDATE transactions SET fingerprint = :fp WHERE id = :id"),
                     {"fp": value, "id": row_id})


